package app.wakeguard

/**
 * Maps a stored [StoredAlarm.soundPack] to a bundled raw resource.
 *
 * One pack is one tone. The alarm and the editor preview both play exactly the
 * same file, for the whole ring, so the sound a user picks is the sound they
 * hear. There is no gentle-to-loud escalation of the audio itself.
 *
 * Kept in one place because the identifiers are generated by
 * `tool/generate_alarms.py`; a typo here compiles fine and then plays nothing.
 * Lookup is defensive: an unknown pack, or an asset that failed to generate,
 * falls back to another tone rather than leaving the alarm silent, because a
 * silent alarm is the exact failure this app exists to prevent.
 */
object AlarmSounds {

    const val DEFAULT_PACK = "pulse"

    /** The generated tier that is used as "the" tone for every pack. */
    private const val TONE = "critical"

    /** Tried only if [TONE] is missing for a pack. */
    private const val FALLBACK_TONE = "gentle"

    /** The families [tool/generate_alarms.py] renders. */
    private val PACKS = listOf("pulse", "siren", "radar", "gong")

    /** The raw resource for [pack]. Never 0. */
    fun resourceFor(context: android.content.Context, pack: String?): Int {
        val safePack = pack?.takeIf { it in PACKS } ?: DEFAULT_PACK
        // Preference order: this pack's tone, then this pack's other file, then
        // the other packs. Always ends on a compile-time-known constant, so this
        // cannot return "no sound".
        val candidates = buildList {
            add("tone_${safePack}_$TONE")
            add("tone_${safePack}_$FALLBACK_TONE")
            for (fallbackPack in PACKS) {
                add("tone_${fallbackPack}_$TONE")
                add("tone_${fallbackPack}_$FALLBACK_TONE")
            }
        }
        for (name in candidates) {
            val id = context.resources.getIdentifier(name, "raw", context.packageName)
            if (id != 0) return id
        }
        // Last resort. This one is a compile-time constant, so it can never be 0.
        return R.raw.tone_pulse_gentle
    }

    /** Every selectable pack, for the Dart UI and health reporting. */
    fun packs(): List<String> = PACKS
}
